def run_agent(model, tools, task, max_steps=5):
    messages = [{"role": "user", "content": task}]
    for _ in range(max_steps):
        reply = model(messages)
        if "answer" in reply:
            messages.append({"role": "assistant", "content": reply["answer"]})
            return reply["answer"], messages
        name = reply["tool"]
        args = reply.get("args", {})
        messages.append({"role": "assistant", "tool": name, "args": args})
        if name not in tools:
            result = {"error": "unknown tool: " + name}
        else:
            try:
                result = tools[name](**args)
            except Exception as exc:
                result = {"error": str(exc)}
        messages.append({"role": "tool", "name": name, "content": result})
    return "stopped: step budget", messages
